      const pos=x=>{ let i=0; while(i<R.length-2 && R[i+1].x<x) i++; const a=R[i], b=R[i+1], f=(x-a.x)/((b.x-a.x)||1);
        return [lerp(a.x,b.x,f), lerp(a.y,b.y,f), lerp(a.z,b.z,f)]; };
