      for(let i=0;i<=nu;i++) for(let j=0;j<=na;j++){ const q=f(i/nu,j/na), u=UH.ux(q[0]), a=UH.az(u,q[1]), p=UH.at(u,a);
        V.push([p[0], p[1]-cut(q[0],q[1])+o.h, p[2]]); N.push(UH.nrm(u,a)); }
